<template>
  <div>
    <router-link class="back-link" to="/applications"><ArrowLeft :size="16" />返回工作台</router-link>
    <div class="page-header">
      <div><h1 class="page-title">{{ application?.name || '应用详情' }}</h1><p class="page-subtitle">{{ application?.project?.name || '-' }} · {{ application?.environment?.name || '-' }} · {{ application?.environment?.namespace || '-' }}</p></div>
      <button class="btn btn-primary" @click="openTemplateEditor()">新建上线模板</button>
    </div>
    <div v-if="error" class="k8s-banner k8s-banner-warn section-gap">{{ error }}</div>

    <section v-if="application" class="detail-section">
      <div class="section-heading"><div><h2>对外域名</h2><p>域名绑定独立于发布版本，变更时会同步应用 Ingress。</p></div><button class="btn btn-sm" @click="openEndpointEditor()">绑定域名</button></div>
      <div v-if="endpoints.length" class="endpoint-list"><div v-for="endpoint in endpoints" :key="endpoint.id" class="endpoint-row"><div><a class="endpoint-url" :href="endpointURL(endpoint)" target="_blank" rel="noopener noreferrer">{{ endpoint.domain }}</a><small>{{ endpoint.path || '/' }} · Service {{ endpoint.service_port }} · {{ endpoint.tls_enabled ? 'HTTPS' : 'HTTP' }}</small></div><div class="btn-group"><button class="btn btn-sm" @click="openEndpointEditor(endpoint)"><Pencil :size="14" /> 编辑</button><button class="btn btn-sm btn-danger" @click="removeEndpoint(endpoint)">解绑</button></div></div></div>
      <div v-else class="empty-inline">当前应用仅限集群内访问</div>
    </section>

    <section v-if="application" class="detail-section">
      <div class="section-heading"><div><h2>工作负载类型</h2><p>Deployment 适用于无状态服务；StatefulSet 用于单副本持久服务。切换会短暂停止服务并复用当前 PVC。</p></div></div>
      <div class="workload-kind-row"><select v-model="workloadKind" class="form-select" aria-label="工作负载类型"><option value="deployment">Deployment</option><option value="statefulset">StatefulSet</option></select><button class="btn btn-sm" :disabled="saving || workloadKind === (application.workload_kind || 'deployment')" @click="updateWorkloadKind">{{ saving ? '迁移中...' : '迁移工作负载' }}</button></div>
    </section>

    <section v-if="application" class="detail-section">
      <div class="section-heading"><div><h2>上线模板</h2><p>模板定义镜像、运行资源、健康检查与 Service；发布时选择模板并填写版本号。</p></div><button class="btn btn-sm" @click="openTemplateEditor()">新建模板</button></div>
      <div v-if="templates.length" class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>模板</th><th>镜像路径</th><th>运行配置</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="template in templates" :key="template.id"><td class="cell-primary">{{ template.name }}<small v-if="template.description">{{ template.description }}</small></td><td>{{ template.spec.image }}</td><td>{{ template.spec.replicas }} 副本 · {{ template.spec.container_port }} 容器端口 · {{ templateServiceSummary(template.spec.service) }}</td><td><span class="badge" :class="template.enabled ? 'badge-online' : 'badge-offline'">{{ template.enabled ? template.is_default ? '默认' : '启用' : '停用' }}</span></td><td><div class="btn-group"><button v-if="template.enabled && !template.is_default" class="btn btn-sm" @click="setDefaultTemplate(template)">设为默认</button><button class="btn btn-sm" @click="openTemplateEditor(template)">编辑</button><button class="btn btn-sm btn-danger" @click="deleteTemplate(template)">删除</button></div></td></tr></tbody></table></div></div>
      <div v-else class="empty-inline">尚未配置上线模板</div>
    </section>

    <section v-if="application && templateDependencies.length" class="detail-section"><div class="section-heading"><div><h2>运行依赖</h2><p>模板引用的文件资源会在发布前再次验证。</p></div><button class="btn btn-sm" @click="openResourceManagement">管理资源</button></div><div class="dependency-list"><div v-for="dependency in templateDependencies" :key="dependency.id" class="dependency-row"><div><strong>{{ dependency.template }}</strong><small>{{ dependency.type }} · {{ dependency.name }} · {{ dependency.key }} → {{ dependency.path }}</small></div><span class="badge" :class="dependency.ready ? 'badge-online' : 'badge-danger'">{{ dependency.ready ? '可用' : '缺失' }}</span></div></div></section>

    <section v-if="application && releases.length" class="detail-section"><div class="section-heading"><div><h2>发布记录</h2><p>每次发布保存独立快照，不会因后续模板或域名变更而改写。</p></div></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>版本</th><th>镜像</th><th>模板</th><th>状态</th><th>时间</th></tr></thead><tbody><tr v-for="release in releases" :key="release.id" class="clickable" @click="openRelease(release)"><td class="cell-primary">{{ release.version || `Release #${release.sequence}` }}</td><td>{{ release.image }}</td><td>{{ templateName(release.template_id) || '-' }}</td><td><span class="badge" :class="releaseBadge(release.status)">{{ release.status }}</span></td><td>{{ formatTime(release.created_at) }}</td></tr></tbody></table></div></div></section>

    <Teleport to="body"><div v-if="showTemplateEditor" class="overlay" @click.self="closeTemplateEditor"><div class="modal editor-modal"><div class="editor-header"><div><h2 class="modal-title">{{ editingTemplate ? '编辑上线模板' : '新建上线模板' }}</h2><p>{{ templateEditorSummary }}</p></div><label class="check-row"><input v-model="templateForm.enabled" type="checkbox" /> 启用</label></div><div class="template-editor-layout"><form id="template-editor-form" class="template-editor-form" @submit.prevent="saveTemplate">
      <section id="template-basic" class="editor-section"><div class="editor-section-heading"><div><h3>基础信息</h3><p>模板标识与镜像来源。</p></div></div><div class="form-row"><div class="form-group"><label class="form-label">模板名称</label><input v-model.trim="templateForm.name" class="form-input" required placeholder="标准生产配置" /></div><div class="form-group"><label class="form-label">说明</label><input v-model.trim="templateForm.description" class="form-input" placeholder="2 副本、HTTP 就绪检查" /></div></div>
      <div class="form-group"><label class="form-label">镜像仓库</label><select v-model.number="templateForm.registry_id" class="form-select"><option :value="0">自定义完整镜像地址</option><option v-for="registry in registries" :key="registry.id" :value="registry.id">{{ registry.name }} · {{ registry.endpoint }}</option></select></div>
      <div class="form-group"><label class="form-label">镜像路径</label><input v-model.trim="templateForm.image" class="form-input" required :placeholder="templateForm.registry_id ? 'commerce/order-api' : 'registry.example.com/order-api'" /><p class="form-hint">模板不包含 Tag，发布时填写版本号。</p></div></section>
      <section id="template-deployment" class="editor-section"><div class="editor-section-heading"><div><h3>服务部署</h3><p>容器启动方式、副本与节点调度。</p></div></div><div class="form-row"><div class="form-group"><div class="volume-heading"><label class="form-label">启动命令</label><button type="button" class="btn btn-sm" @click="addCommandItem">+ 添加命令</button></div><div v-if="templateForm.command_items.length" class="value-list"><div v-for="(item, index) in templateForm.command_items" :key="index" class="value-row"><input v-model="item.value" class="form-input" placeholder="/usr/bin/chromium-browser" /><button type="button" class="icon-button" title="移除启动命令" @click="removeCommandItem(index)"><Trash2 :size="16" /></button></div></div><p class="form-hint">留空则使用镜像默认入口命令。</p></div><div class="form-group"><div class="volume-heading"><label class="form-label">启动参数</label><button type="button" class="btn btn-sm" @click="addArgumentItem">+ 添加参数</button></div><div v-if="templateForm.argument_items.length" class="value-list"><div v-for="(item, index) in templateForm.argument_items" :key="index" class="value-row"><input v-model="item.value" class="form-input" placeholder="--remote-debugging-port=9222" /><button type="button" class="icon-button" title="移除启动参数" @click="removeArgumentItem(index)"><Trash2 :size="16" /></button></div></div><p class="form-hint">每行一个参数项，不执行 Shell 解析。</p></div></div>
      <div class="form-row"><div class="form-group"><label class="form-label">容器端口</label><input v-model.number="templateForm.container_port" type="number" min="1" class="form-input" required /></div><div class="form-group"><label class="form-label">副本数</label><input v-model.number="templateForm.replicas" type="number" min="1" class="form-input" :disabled="templateForm.volumes.length > 0" required /><p v-if="templateForm.volumes.length" class="form-hint">ReadWriteOnce 存储卷仅支持单副本。</p></div></div>
      <div class="form-group"><label class="form-label">部署节点</label><select v-model="templateForm.node_name" class="form-select"><option value="">由 Kubernetes 调度</option><option v-for="node in clusterNodes" :key="node.name" :value="node.name">{{ node.display_name }} · hostname={{ node.name }}</option></select><p class="form-hint">选择后将使用 kubernetes.io/hostname 标签调度；本地 PVC 必须与其已绑定节点一致，首次挂载 local-path PVC 时将决定数据落盘节点。</p></div></section>
      <section id="template-storage" class="editor-section"><div class="editor-section-heading"><div><h3>配置与存储</h3><p>应用配置、敏感信息与挂载资源。</p></div></div><div class="form-group"><div class="volume-heading"><label class="form-label">数据卷挂载</label><button type="button" class="btn btn-sm" :disabled="!persistentVolumeClaims.length" @click="addVolume">+ 添加挂载</button></div><div v-if="templateForm.volumes.length" class="volume-list"><div v-for="(volume, index) in templateForm.volumes" :key="index" class="volume-row"><select v-model="volume.claim_name" class="form-select"><option v-for="claim in persistentVolumeClaims" :key="claim.name" :value="claim.name">{{ claim.name }} · {{ claim.phase || 'Pending' }}</option></select><input v-model.trim="volume.mount_path" class="form-input" required placeholder="/data" /><label class="check-row"><input v-model="volume.read_only" type="checkbox" /> 只读</label><button type="button" class="icon-button" title="移除数据卷挂载" @click="removeVolume(index)"><Trash2 :size="16" /></button></div></div><p v-else class="form-hint">未配置数据卷，应用将按无状态方式发布。</p></div>
      <div class="form-group tls-certificate-field"><div class="volume-heading"><label class="form-label">TLS 证书</label><button type="button" class="btn btn-sm" @click="openCertificateManagement">申请证书</button></div><div class="tls-helper"><select v-model="templateForm.tls_secret_name" class="form-select" aria-label="TLS 证书"><option value="">选择当前环境已就绪证书</option><option v-for="certificate in readyTLSCertificates" :key="certificate.id" :value="certificate.tls_secret_name">{{ certificate.hostname }} · {{ certificate.tls_secret_name }}</option></select><input v-model.trim="templateForm.tls_mount_dir" class="form-input" aria-label="TLS 挂载目录" placeholder="/etc/tls" /><button type="button" class="btn btn-sm btn-primary" :disabled="!templateForm.tls_secret_name" @click="addTLSCertificateMounts">添加挂载</button></div><p class="form-hint">会添加标准 Secret 的 tls.crt 和 tls.key 文件挂载，不创建 HTTP Ingress。</p></div>
      <div class="form-row"><div class="form-group"><div class="volume-heading"><label class="form-label">ConfigMap 环境变量</label><button type="button" class="btn btn-sm" @click="addConfigItem">+ 添加变量</button></div><div v-if="templateForm.config_items.length" class="key-value-list"><div v-for="(item, index) in templateForm.config_items" :key="index" class="key-value-row"><input v-model.trim="item.key" class="form-input" placeholder="变量名或文件名" /><textarea v-model="item.value" class="form-input config-value-input" rows="1" placeholder="变量值或文件内容"></textarea><button type="button" class="icon-button" title="移除 ConfigMap 变量" @click="removeConfigItem(index)"><Trash2 :size="16" /></button></div></div><p class="form-hint">发布时生成应用专属 ConfigMap；其中的 key 也可挂载为文件。</p></div><div class="form-group"><div class="volume-heading"><label class="form-label">Secret 环境变量</label><button type="button" class="btn btn-sm" @click="addSecretItem">+ 添加变量</button></div><div v-if="templateForm.secret_items.length" class="key-value-list"><div v-for="(item, index) in templateForm.secret_items" :key="index" class="key-value-row"><input v-model.trim="item.key" class="form-input" placeholder="变量名" /><input v-model="item.value" type="password" class="form-input" placeholder="变量值" /><button type="button" class="icon-button" title="移除 Secret 变量" @click="removeSecretItem(index)"><Trash2 :size="16" /></button></div></div><p class="form-hint">编辑时留空会保留已有值。</p></div></div><div class="form-group"><div class="volume-heading"><label class="form-label">配置文件挂载</label><button type="button" class="btn btn-sm" @click="addFileMount">+ 添加挂载</button></div><div v-if="templateForm.file_mounts.length" class="file-mount-list"><div v-for="(fileMount, index) in templateForm.file_mounts" :key="index" class="file-mount-row"><select v-model="fileMount.source_type" class="form-select" aria-label="文件来源类型" @change="resetFileMountSource(fileMount)"><option value="application_config">当前应用 ConfigMap</option><option value="configmap">已有 ConfigMap</option><option value="secret">已有 Secret</option></select><input v-if="fileMount.source_type === 'application_config'" class="form-input" :value="applicationConfigName" aria-label="文件来源资源" disabled /><select v-else v-model="fileMount.source_name" class="form-select" required aria-label="文件来源资源"><option value="" disabled>选择资源</option><option v-for="resource in fileMountResources(fileMount.source_type)" :key="resource.name" :value="resource.name">{{ resource.name }}</option></select><select v-model="fileMount.key" class="form-select" required aria-label="文件来源键"><option value="" disabled>选择 Key</option><option v-for="key in fileMountKeys(fileMount)" :key="key" :value="key">{{ key }}</option></select><input v-model.trim="fileMount.mount_path" class="form-input" required placeholder="/etc/app/config.yaml" /><button type="button" class="icon-button" title="移除配置文件挂载" @click="removeFileMount(index)"><Trash2 :size="16" /></button></div></div><p v-else class="form-hint">当前应用 ConfigMap 的 key 可直接投影为文件；也可挂载当前命名空间已有的 ConfigMap 或 Secret。</p></div></section>
      <section id="template-resources" class="editor-section"><div class="editor-section-heading"><div><h3>资源与健康</h3><p>运行资源与容器就绪状态。</p></div></div><div class="form-row"><QuantityInput label="CPU 请求" v-model:value="templateForm.resources.requests_cpu" v-model:unit="templateForm.resources.requests_cpu_unit" :units="['m', '']" /><QuantityInput label="CPU 限制" v-model:value="templateForm.resources.limits_cpu" v-model:unit="templateForm.resources.limits_cpu_unit" :units="['m', '']" /></div>
      <div class="form-row"><QuantityInput label="内存请求" v-model:value="templateForm.resources.requests_memory" v-model:unit="templateForm.resources.requests_memory_unit" :units="['Mi', 'Gi']" /><QuantityInput label="内存限制" v-model:value="templateForm.resources.limits_memory" v-model:unit="templateForm.resources.limits_memory_unit" :units="['Mi', 'Gi']" /></div>
      <div v-if="!hasTCPServicePort" class="form-hint">仅 UDP Service 不支持当前 HTTP/TCP 健康检查；请通过 Pod 状态和 Service Endpoint 观察运行状态。</div><div v-else class="form-row"><div class="form-group"><label class="check-row"><input v-model="templateForm.health.readiness_enabled" type="checkbox" /> 启用就绪检查</label><div v-if="templateForm.health.readiness_enabled" class="form-row"><select v-model="templateForm.health.readiness_type" class="form-select"><option value="http">HTTP</option><option value="tcp">TCP</option></select><input v-if="templateForm.health.readiness_type === 'http'" v-model="templateForm.health.readiness_path" class="form-input" /></div></div><div class="form-group"><label class="check-row"><input v-model="templateForm.health.liveness_enabled" type="checkbox" /> 启用存活检查</label><div v-if="templateForm.health.liveness_enabled" class="form-row"><select v-model="templateForm.health.liveness_type" class="form-select"><option value="http">HTTP</option><option value="tcp">TCP</option></select><input v-if="templateForm.health.liveness_type === 'http'" v-model="templateForm.health.liveness_path" class="form-input" /></div></div></div></section>
      <section id="template-network" class="editor-section"><div class="editor-section-heading"><div><h3>服务网络</h3><p>Service 暴露方式和端口映射。</p></div></div><div class="form-row"><div class="form-group"><label class="form-label">Service 类型</label><select v-model="templateForm.service.type" class="form-select"><option value="ClusterIP">ClusterIP</option><option value="NodePort">NodePort</option><option value="LoadBalancer">LoadBalancer</option></select><p class="form-hint">{{ serviceTypeHint }}</p></div><div v-if="templateForm.service.type !== 'ClusterIP'" class="form-group"><label class="form-label">外部流量策略</label><select v-model="templateForm.service.external_traffic_policy" class="form-select"><option value="">使用集群默认值</option><option value="Cluster">Cluster</option><option value="Local">Local</option></select></div></div>
      <div class="form-group"><div class="volume-heading"><label class="form-label">Service 端口</label><button type="button" class="btn btn-sm" @click="addServicePort">+ 添加端口</button></div><div class="service-port-list" :class="{ 'with-node-port': templateForm.service.type === 'NodePort' }"><div class="service-port-headings"><span>名称</span><span>协议</span><span>Service 端口</span><span>Target Port</span><span v-if="templateForm.service.type === 'NodePort'">NodePort（可选）</span><span></span></div><div v-for="(servicePort, index) in templateForm.service.ports" :key="index" class="service-port-row"><input v-model.trim="servicePort.name" class="form-input" required aria-label="Service 端口名称" placeholder="端口名称" /><select v-model="servicePort.protocol" class="form-select" aria-label="传输协议"><option value="TCP">TCP</option><option value="UDP">UDP</option></select><input v-model.number="servicePort.port" type="number" min="1" class="form-input" required aria-label="Service 端口" placeholder="Service 端口" /><input v-model.number="servicePort.target_port" type="number" min="1" class="form-input" required aria-label="Target Port" placeholder="Target Port" /><input v-if="templateForm.service.type === 'NodePort'" v-model.number="servicePort.node_port" type="number" min="1" class="form-input" aria-label="NodePort" placeholder="自动分配" /><button type="button" class="icon-button" title="移除 Service 端口" :disabled="templateForm.service.ports.length === 1" @click="removeServicePort(index)"><Trash2 :size="16" /></button></div></div><p v-if="templateForm.service.type === 'NodePort'" class="form-hint">留空由 Kubernetes 自动分配 NodePort；发布完成后使用节点 IP 和实际分配端口访问。</p><p v-if="hasTCPServicePort" class="form-hint">HTTP 服务保存模板并发布后，在页面顶部“对外域名”绑定已就绪域名，平台会创建 HTTP Ingress 并转发到第一个 TCP Service 端口。Ingress 只转发 HTTP/HTTPS；其他 TCP 协议请使用 NodePort 或 LoadBalancer。</p><p v-else class="form-hint">仅 UDP Service 不支持 HTTP Ingress；请使用 NodePort 或 LoadBalancer 直接暴露端口。</p></div></section>
    </form><div class="modal-actions editor-actions"><button type="button" class="btn" @click="closeTemplateEditor">取消</button><button form="template-editor-form" class="btn btn-primary" :disabled="saving">{{ saving ? '保存中...' : '保存模板' }}</button></div></div></div></div></Teleport>
    <Teleport to="body"><div v-if="showEndpointEditor" class="overlay" @click.self="closeEndpointEditor"><div class="modal"><h2 class="modal-title">{{ editingEndpoint ? '编辑对外域名' : '绑定对外域名' }}</h2><form @submit.prevent="saveEndpoint"><div class="form-group"><label class="form-label">受管域名</label><select v-model.number="endpointForm.domain_id" class="form-select" required><option :value="0" disabled>选择当前环境的已就绪域名</option><option v-for="domain in readyDomains" :key="domain.id" :value="domain.id">{{ domain.hostname }}</option></select></div><div class="form-group"><label class="form-label">访问路径</label><input v-model.trim="endpointForm.path" class="form-input" required placeholder="/" /></div><label class="check-row"><input v-model="endpointForm.tls_enabled" type="checkbox" /> 启用 HTTPS</label><div class="modal-actions"><button type="button" class="btn" @click="closeEndpointEditor">取消</button><button class="btn btn-primary" :disabled="saving">{{ saving ? '保存中...' : '保存绑定' }}</button></div></form></div></div></Teleport>
  </div>
</template>

<script setup>
import { computed, defineComponent, h, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowLeft, Pencil, Trash2 } from 'lucide-vue-next'
import { api } from '../api/index.js'

const QuantityInput = defineComponent({
  props: { label: String, value: Number, unit: String, units: Array }, emits: ['update:value', 'update:unit'],
  setup(props, { emit }) {
    return () => h('div', { class: 'form-group' }, [
      h('label', { class: 'form-label' }, props.label),
      h('div', { class: 'unit-input' }, [
        h('input', { class: 'form-input', type: 'number', min: 1, value: props.value, onInput: event => emit('update:value', Number(event.target.value)) }),
        h('select', { class: 'form-select', value: props.unit, onChange: event => emit('update:unit', event.target.value) }, props.units.map(unit => h('option', { value: unit }, unit || '核'))),
      ]),
    ])
  },
})

const props = defineProps({ applicationID: { type: String, required: true } })
const router = useRouter()
const application = ref(null)
const releases = ref([])
const templates = ref([])
const endpoints = ref([])
const domains = ref([])
const registries = ref([])
const configResources = ref([])
const secretResources = ref([])
const persistentVolumeClaims = ref([])
const clusterNodes = ref([])
const storageResourcesLoaded = ref(false)
const storageResourcesLoading = ref(false)
const error = ref('')
const saving = ref(false)
const showTemplateEditor = ref(false)
const editingTemplate = ref(null)
const showEndpointEditor = ref(false)
const editingEndpoint = ref(null)
const workloadKind = ref('deployment')
const templateForm = ref(newTemplateForm())
const endpointForm = ref(newEndpointForm())

const readyDomains = computed(() => domains.value.filter(domain => domain.enabled && domain.certificate?.status === 'Ready'))
const readyTLSCertificates = computed(() => readyDomains.value.filter(domain => domain.tls_secret_name))
const applicationConfigName = computed(() => application.value ? `${application.value.name}-config` : '应用配置')
const templateDependencies = computed(() => templates.value.flatMap(template => (template.spec?.file_mounts || []).map((mount, index) => {
  if (mount.source_type === 'application_config') {
    return { id: `${template.id}-${index}`, template: template.name, type: '应用 ConfigMap', name: `${application.value?.name || '应用'}-config`, key: mount.key, path: mount.mount_path, ready: Object.prototype.hasOwnProperty.call(template.spec?.config || {}, mount.key) }
  }
  const resource = fileMountResources(mount.source_type).find(item => item.name === mount.source_name)
  return { id: `${template.id}-${index}`, template: template.name, type: mount.source_type === 'secret' ? 'Secret' : 'ConfigMap', name: mount.source_name, key: mount.key, path: mount.mount_path, ready: !!resource && (resource.keys || []).includes(mount.key) }
})))
const hasTCPServicePort = computed(() => templateForm.value.service.ports.some(port => port.protocol === 'TCP'))
const templateEditorSummary = computed(() => `${templateForm.value.replicas} 副本 · ${templateServiceSummary(templateForm.value.service)}`)
const serviceTypeHint = computed(() => ({
  ClusterIP: '仅集群内访问；HTTP 服务可通过域名入口暴露。',
  NodePort: '通过节点 IP 和端口访问；需配置外部网络策略。',
  LoadBalancer: '由集群负载均衡器分配外部地址，适用于 TCP 或 UDP 直出。',
}[templateForm.value.service.type] || ''))

function newServicePort(index, targetPort) { return { name: `port-${index}`, port: 80, target_port: targetPort, protocol: 'TCP', node_port: null } }
function servicePortsFromSpec(service, containerPort) { const ports = service?.ports?.length ? service.ports : [{ name: 'service', port: service?.port || 80, target_port: service?.target_port || containerPort, protocol: service?.protocol || 'TCP', node_port: service?.node_port || null }]; return ports.map((port, index) => ({ name: port.name || `port-${index + 1}`, port: port.port, target_port: port.target_port, protocol: port.protocol || 'TCP', node_port: port.node_port || null })) }
function newTemplateForm() { return { name: '', description: '', enabled: true, registry_id: 0, image: '', command_items: [], argument_items: [], container_port: 8080, replicas: 1, node_name: '', volumes: [], file_mounts: [], tls_secret_name: '', tls_mount_dir: '/etc/tls', config_items: [], secret_items: [], resources: { requests_cpu: 100, requests_cpu_unit: 'm', requests_memory: 128, requests_memory_unit: 'Mi', limits_cpu: 500, limits_cpu_unit: 'm', limits_memory: 512, limits_memory_unit: 'Mi' }, health: { readiness_enabled: true, readiness_type: 'http', readiness_path: '/healthz', liveness_enabled: false, liveness_type: 'http', liveness_path: '/healthz' }, service: { type: 'ClusterIP', external_traffic_policy: '', ports: [newServicePort(1, 8080)] } } }
function newEndpointForm() { return { domain_id: 0, path: '/', tls_enabled: true } }
function endpointURL(endpoint) { return `${endpoint.tls_enabled ? 'https' : 'http'}://${endpoint.domain}${endpoint.path || '/'}` }
function releaseBadge(status) { return status === 'succeeded' ? 'badge-online' : status === 'failed' ? 'badge-danger' : 'badge-offline' }
function formatTime(value) { return value ? new Date(value).toLocaleString() : '-' }
function templateName(id) { return templates.value.find(template => template.id === id)?.name }
function quantityInput(value, unit) { const match = String(value || '').match(/^(\d+)(m|Mi|Gi)?$/); return { value: match ? Number(match[1]) : 1, unit: match?.[2] ?? unit } }
function formFromTemplate(template) { const spec = template.spec; const requestCPU = quantityInput(spec.resources?.requests_cpu, 'm'), requestMemory = quantityInput(spec.resources?.requests_memory, 'Mi'), limitCPU = quantityInput(spec.resources?.limits_cpu, 'm'), limitMemory = quantityInput(spec.resources?.limits_memory, 'Mi'); return { ...newTemplateForm(), name: template.name, description: template.description || '', enabled: template.enabled, registry_id: spec.registry_id || 0, image: spec.image, command_items: stringItems(spec.command), argument_items: stringItems(spec.args), container_port: spec.container_port, replicas: spec.replicas, node_name: spec.node_name || '', volumes: (spec.volumes || []).map(volume => ({ claim_name: volume.claim_name, mount_path: volume.mount_path, read_only: !!volume.read_only })), file_mounts: (spec.file_mounts || []).map(fileMount => ({ source_type: fileMount.source_type, source_name: fileMount.source_name, key: fileMount.key, mount_path: fileMount.mount_path })), config_items: keyValueItems(spec.config), secret_items: Object.keys(spec.secrets || {}).map(key => ({ key, value: '' })), resources: { requests_cpu: requestCPU.value, requests_cpu_unit: requestCPU.unit, requests_memory: requestMemory.value, requests_memory_unit: requestMemory.unit, limits_cpu: limitCPU.value, limits_cpu_unit: limitCPU.unit, limits_memory: limitMemory.value, limits_memory_unit: limitMemory.unit }, health: { ...newTemplateForm().health, ...spec.health }, service: { type: spec.service?.type || 'ClusterIP', external_traffic_policy: spec.service?.external_traffic_policy || '', ports: servicePortsFromSpec(spec.service, spec.container_port) } } }
function stringItems(values) { return (values || []).map(value => ({ value })) }
function keyValueItems(values) { return Object.entries(values || {}).map(([key, value]) => ({ key, value })) }
function stringValues(items) { return items.map(item => item.value.trim()).filter(Boolean) }
function keyValueMap(items) { return items.reduce((result, item) => { if (item.key.trim()) result[item.key.trim()] = item.value; return result }, {}) }
function fileMountResources(sourceType) { return sourceType === 'secret' ? secretResources.value : configResources.value }
function fileMountKeys(fileMount) { if (fileMount.source_type === 'application_config') return templateForm.value.config_items.map(item => item.key.trim()).filter(Boolean); return fileMountResources(fileMount.source_type).find(resource => resource.name === fileMount.source_name)?.keys || [] }
function resetFileMountSource(fileMount) { fileMount.source_name = ''; fileMount.key = '' }
function addTLSCertificateMounts() { const directory = templateForm.value.tls_mount_dir.replace(/\/$/, '') || '/etc/tls'; const secretName = templateForm.value.tls_secret_name; const mounts = templateForm.value.file_mounts; for (const key of ['tls.crt', 'tls.key']) { const mountPath = `${directory}/${key}`; const existing = mounts.find(item => item.mount_path === mountPath); if (existing) { existing.source_type = 'secret'; existing.source_name = secretName; existing.key = key } else mounts.push({ source_type: 'secret', source_name: secretName, key, mount_path: mountPath }) } }
function templatePayload() { const form = templateForm.value; const service = { type: form.service.type, external_traffic_policy: form.service.type === 'ClusterIP' ? '' : form.service.external_traffic_policy, ports: form.service.ports.map(port => ({ name: port.name, port: port.port, target_port: port.target_port, protocol: port.protocol, node_port: form.service.type === 'NodePort' ? port.node_port || 0 : 0 })) }; return { name: form.name, description: form.description, enabled: form.enabled, spec: { image: form.image, registry_id: form.registry_id, command: stringValues(form.command_items), args: stringValues(form.argument_items), container_port: form.container_port, replicas: form.replicas, node_name: form.node_name, volumes: form.volumes, file_mounts: form.file_mounts, config: keyValueMap(form.config_items), secrets: keyValueMap(form.secret_items), resources: { requests_cpu: `${form.resources.requests_cpu}${form.resources.requests_cpu_unit}`, requests_memory: `${form.resources.requests_memory}${form.resources.requests_memory_unit}`, limits_cpu: `${form.resources.limits_cpu}${form.resources.limits_cpu_unit}`, limits_memory: `${form.resources.limits_memory}${form.resources.limits_memory_unit}` }, health: hasTCPServicePort.value ? form.health : { ...form.health, readiness_enabled: false, liveness_enabled: false }, service } } }
function templateServiceSummary(service) { const ports = servicePortsFromSpec(service, 0); return `${service?.type || 'ClusterIP'} · ${ports.map(port => `${port.protocol} ${port.port}`).join(', ')}` }

async function refreshFileResources(namespace = application.value?.environment?.namespace || '') { const [configmaps, secrets] = await Promise.all([api.get(`/k8s/configmaps?namespace=${encodeURIComponent(namespace)}&usage=false`), api.get(`/k8s/secrets?namespace=${encodeURIComponent(namespace)}&usage=false`)]); configResources.value = configmaps || []; secretResources.value = secrets || [] }
async function loadApplication() { error.value = ''; storageResourcesLoaded.value = false; persistentVolumeClaims.value = []; clusterNodes.value = []; try { const result = await api.get(`/applications/${props.applicationID}`); application.value = result.application; workloadKind.value = result.application.workload_kind || 'deployment'; releases.value = result.releases || []; const namespace = result.application.environment?.namespace || ''; const [loadedTemplates, loadedEndpoints, loadedDomains, loadedRegistries] = await Promise.all([api.get(`/applications/${props.applicationID}/deployment-templates`), api.get(`/applications/${props.applicationID}/endpoints`), api.get(`/domains?environment_id=${result.application.environment_id}`), api.get(`/image-registries?project_id=${result.application.project_id}`), refreshFileResources(namespace)]); templates.value = loadedTemplates || []; endpoints.value = loadedEndpoints || []; domains.value = loadedDomains || []; registries.value = loadedRegistries || [] } catch (e) { error.value = e.message || '加载应用详情失败' } }
async function loadStorageResources() { if (storageResourcesLoaded.value || storageResourcesLoading.value || !application.value) return; storageResourcesLoading.value = true; try { const storage = await Promise.allSettled([api.get(`/k8s/persistent-volume-claims?environment_id=${application.value.environment_id}`), api.get('/nodes'), api.get('/servers')]); persistentVolumeClaims.value = storage[0].status === 'fulfilled' ? storage[0].value || [] : []; const servers = storage[2].status === 'fulfilled' ? storage[2].value || [] : []; const serverNames = new Map(servers.filter(server => server.k8s_node_name).map(server => [server.k8s_node_name, server.name])); clusterNodes.value = storage[1].status === 'fulfilled' ? (storage[1].value || []).map(node => ({ name: node.name, display_name: serverNames.get(node.name) || node.name })) : []; storageResourcesLoaded.value = true } finally { storageResourcesLoading.value = false } }
async function openRelease(release) { await router.push(`/applications/${props.applicationID}/releases/${release.id}`) }
function openTemplateEditor(template = null) { editingTemplate.value = template; templateForm.value = template ? formFromTemplate(template) : newTemplateForm(); showTemplateEditor.value = true; loadStorageResources() }
function closeTemplateEditor() { showTemplateEditor.value = false; editingTemplate.value = null }
function addCommandItem() { templateForm.value.command_items.push({ value: '' }) }
function removeCommandItem(index) { templateForm.value.command_items.splice(index, 1) }
function addArgumentItem() { templateForm.value.argument_items.push({ value: '' }) }
function removeArgumentItem(index) { templateForm.value.argument_items.splice(index, 1) }
function addConfigItem() { templateForm.value.config_items.push({ key: '', value: '' }) }
function removeConfigItem(index) { templateForm.value.config_items.splice(index, 1) }
function addSecretItem() { templateForm.value.secret_items.push({ key: '', value: '' }) }
function removeSecretItem(index) { templateForm.value.secret_items.splice(index, 1) }
function addVolume() { const claim = persistentVolumeClaims.value[0]; if (claim) templateForm.value.volumes.push({ claim_name: claim.name, mount_path: '/data', read_only: false }) }
function removeVolume(index) { templateForm.value.volumes.splice(index, 1) }
function addFileMount() { templateForm.value.file_mounts.push({ source_type: 'application_config', source_name: '', key: '', mount_path: '' }) }
function removeFileMount(index) { templateForm.value.file_mounts.splice(index, 1) }
async function openResourceManagement() { await router.push('/resources?tab=configs') }
async function openCertificateManagement() { await router.push('/domains') }
function addServicePort() { const ports = templateForm.value.service.ports; ports.push(newServicePort(ports.length + 1, templateForm.value.container_port)) }
function removeServicePort(index) { if (templateForm.value.service.ports.length > 1) templateForm.value.service.ports.splice(index, 1) }
async function saveTemplate() { saving.value = true; error.value = ''; try { const path = `/applications/${props.applicationID}/deployment-templates`; if (editingTemplate.value) await api.put(`${path}/${editingTemplate.value.id}`, templatePayload()); else await api.post(path, templatePayload()); closeTemplateEditor(); await loadApplication() } catch (e) { error.value = e.message || '保存上线模板失败' } finally { saving.value = false } }
async function setDefaultTemplate(template) { try { await api.post(`/applications/${props.applicationID}/deployment-templates/${template.id}/default`); await loadApplication() } catch (e) { error.value = e.message || '设置默认模板失败' } }
async function deleteTemplate(template) { try { await api.delete(`/applications/${props.applicationID}/deployment-templates/${template.id}`); await loadApplication() } catch (e) { error.value = e.message || '删除上线模板失败' } }
function openEndpointEditor(endpoint = null) { editingEndpoint.value = endpoint; endpointForm.value = endpoint ? { domain_id: endpoint.domain_id, path: endpoint.path || '/', tls_enabled: endpoint.tls_enabled } : newEndpointForm(); showEndpointEditor.value = true }
function closeEndpointEditor() { showEndpointEditor.value = false; editingEndpoint.value = null; endpointForm.value = newEndpointForm() }
async function saveEndpoint() { saving.value = true; error.value = ''; try { const current = editingEndpoint.value; const saved = current ? await api.put(`/applications/${props.applicationID}/endpoints/${current.id}`, endpointForm.value) : await api.post(`/applications/${props.applicationID}/endpoints`, endpointForm.value); if (current) endpoints.value = endpoints.value.map(endpoint => endpoint.id === saved.id ? saved : endpoint); else endpoints.value = [...endpoints.value, saved]; closeEndpointEditor() } catch (e) { error.value = e.message || '保存域名绑定失败' } finally { saving.value = false } }
async function removeEndpoint(endpoint) { try { await api.delete(`/applications/${props.applicationID}/endpoints/${endpoint.id}`); endpoints.value = endpoints.value.filter(item => item.id !== endpoint.id) } catch (e) { error.value = e.message || '解绑域名失败' } }
async function updateWorkloadKind() { if (!window.confirm('切换会先停止当前 Pod，再创建新的工作负载控制器。服务会短暂中断，是否继续？')) return; saving.value = true; error.value = ''; try { application.value = await api.put(`/applications/${props.applicationID}/workload-kind`, { workload_kind: workloadKind.value }) } catch (e) { error.value = e.message || '迁移工作负载失败'; workloadKind.value = application.value?.workload_kind || 'deployment' } finally { saving.value = false } }
watch(() => props.applicationID, loadApplication, { immediate: true })
watch(hasTCPServicePort, hasTCP => { if (!hasTCP) { templateForm.value.health.readiness_enabled = false; templateForm.value.health.liveness_enabled = false } })
watch(() => templateForm.value.volumes.length, count => { if (count) templateForm.value.replicas = 1 })
watch(() => templateForm.value.volumes.map(volume => volume.claim_name).join(','), () => { const bound = templateForm.value.volumes.map(volume => persistentVolumeClaims.value.find(claim => claim.name === volume.claim_name)).find(claim => claim?.bound_node); if (bound?.bound_node) templateForm.value.node_name = bound.bound_node })
</script>

